insert into evidence (candidate_id, title, evidence_type, source_name, source_url, publication_date, summary, verification_status) values
  ((select id from candidates where full_name ilike '%martel%' limit 1), 'Sanctions canadiennes (Affaires mondiales Canada)', 'Sanction administrative', 'Affaires mondiales Canada', 'https://www.canada.ca/en/global-affairs/news/2023/01/canada-imposes-additional-sanctions-against-haitian-elites.html', '2022-11-01', 'Martelly, avec Laurent Lamothe et Jean-Henry Céant, sanctionné par le Canada pour « actes de corruption significative » contribuant à financer des groupes armés. Gel des avoirs, interdiction de transaction.', 'Non vérifié'),
  ((select id from candidates where full_name ilike '%martel%' limit 1), 'Sanctions OFAC (Trésor américain)', 'Sanction administrative', 'US Department of the Treasury', 'https://home.treasury.gov/news/press-releases/jy2542', '2024-08-20', 'Martelly placé sur la liste de sanctions du Trésor américain, accusé de faciliter le trafic de cocaïne et de financer des gangs. Sanction administrative, pas une condamnation judiciaire.', 'Non vérifié'),
  ((select id from candidates where full_name ilike '%martel%' limit 1), 'Sanction de l''Union européenne', 'Sanction administrative', 'ABC News (rapportant une sanction de l''UE)', 'https://abcnews.com/amp/International/wireStory/sanctioned-former-president-michel-martelly-returns-haiti-cheer-134793965', NULL, 'Selon ABC News, l''Union européenne aurait également imposé une interdiction de voyage / gel des avoirs à Martelly, en plus du Canada et des États-Unis. À confirmer auprès d''une source officielle de l''UE.', 'Non vérifié'),
  ((select id from candidates where full_name ilike '%martel%' limit 1), 'Rapport ULCC — fausse déclaration de patrimoine', 'Enquête en cours', 'ULCC (Unité de Lutte Contre la Corruption), via Le Nouvelliste', 'https://lenouvelliste.com/en/article/262361/ulcc-hands-over-five-investigation-reports-targeting-a-minister-a-dg-and-former-officials', '2025-12-08', 'L''ULCC a transmis à la justice 5 rapports d''enquête, dont un visant Martelly pour « fausse déclaration de patrimoine ». Rapport d''enquête transmis au judiciaire, PAS une décision judiciaire définitive.', 'Non vérifié'),
  ((select id from candidates where full_name ilike '%martel%' limit 1), 'Demande d''enquête ULCC par la société civile (ECC)', 'Allégation attribuée', 'Ensemble contre la Corruption (ECC), via Le Nouvelliste', 'https://lenouvelliste.com/en/article/250038/lecc-demande-a-lulcc-denqueter-sur-les-biens-accumules-par-michel-joseph-martelly-et-consorts', '2024-09-01', 'L''organisation de la société civile ECC a formellement demandé à l''ULCC d''enquêter sur les biens accumulés par Martelly — antérieur au rapport ULCC de décembre 2025.', 'Non vérifié'),
  ((select id from candidates where full_name ilike '%martel%' limit 1), 'Rapport CSCCA — dossier PetroCaribe', 'Enquête en cours', 'CSCCA (Cour Supérieure des Comptes et du Contentieux Administratif)', 'https://cscca.gouv.ht/uploads/documents/1748211406_petrocaribe_rapport_1_31_janv_2019l.pdf', '2019-05-31', 'Rapport officiel sur 2,3 milliards $ dépensés 2008-2016 ; lacunes importantes dans la planification/exécution des programmes sous le mandat Martelly (2011-2016) ; plus de 15 responsables cités. Aucune condamnation judiciaire de Martelly lui-même à ce jour.', 'Non vérifié'),
  ((select id from candidates where full_name ilike '%martel%' limit 1), 'Priorités annoncées au discours d''investiture', 'Déclaration du candidat', 'International Crisis Group', 'https://crisisgroup.org/node/4487', '2011-04-01', 'Discours d''investiture (D01) : priorités déclarées — éducation, collecte fiscale, sécurité, investissement étranger. Aucun plan stratégique détaillé officiel retrouvé au-delà de ces annonces.', 'Non vérifié'),
  ((select id from candidates where full_name ilike '%martel%' limit 1), 'Programme « Ti Manman Cheri »', 'Programme ou engagement public', 'CaribJournal / base de données CEPALC (ONU)', 'https://dds.cepal.org/bpsnc/programme?id=58', '2012-05-27', 'Transfert monétaire conditionnel pour mères (D02), lancé à Cité Soleil, financé par PetroCaribe, objectif 100 000 bénéficiaires, 13 M$ la première année.', 'Non vérifié'),
  ((select id from candidates where full_name ilike '%martel%' limit 1), 'Allégation de financement de gangs (rapport d''experts ONU)', 'Allégation attribuée', 'Rapport d''experts ONU, cité par CETRI/CIVICUS', 'https://cetri.be/IMG/pdf/cetri.be-haiti_etat_des_gangs_dans_un_pays_sans_etat.pdf', '2023-01-01', 'D03 : un rapport d''experts de l''ONU évoque Martelly parmi des personnalités ayant fourni des ressources à des gangs. Allégation attribuée, cohérente avec la sanction OFAC 2024, mais pas une condamnation.', 'Non vérifié'),
  ((select id from candidates where full_name ilike '%martel%' limit 1), 'Relations diplomatiques avec Taïwan', 'Document officiel / source primaire', 'Bureau du Président de Taïwan', 'https://english.president.gov.tw/NEWS/4394', '2014-04-01', 'D04 : Haïti a maintenu sa reconnaissance de Taïwan (pas la Chine) tout au long du mandat. Visites officielles réciproques documentées (2013-2014).', 'Non vérifié'),
  ((select id from candidates where full_name ilike '%martel%' limit 1), 'Programme PSUGO (scolarisation universelle gratuite)', 'Programme ou engagement public', 'UNESCO', 'https://unesdoc.unesco.org/in/rest/annotationSVC/DownloadWatermarkedAttachment/attach_import_f23a45ba-c0fb-4392-ae7e-4346dc76b3ac', NULL, 'D06 : programme PSUGO, chiffre officiel de 1M+ enfants inscrits. Des critiques indépendantes (Canada-Haiti) évoquent un financement opaque et des résultats contestés — voir entrée séparée.', 'Non vérifié'),
  ((select id from candidates where full_name ilike '%martel%' limit 1), 'Critiques indépendantes du programme PSUGO', 'Allégation attribuée', 'Canada-Haiti Action Network', 'https://canada-haiti.ca/content/michel-martelly%E2%80%99s-education-plan-haiti-marked-mismanagement-and-inflated-claims', NULL, 'D06 : critique indépendante alléguant une mauvaise gestion et des chiffres gonflés dans le programme PSUGO. Source non officielle — à recouper.', 'Non vérifié'),
  ((select id from candidates where full_name ilike '%martel%' limit 1), 'Programme « Ede Pèp » (carte d''assurance santé)', 'Programme ou engagement public', 'CaribJournal', 'https://www.caribjournal.com/2012/05/29/haitis-martelly-opens-therapy-centre-launches-insurance-card-initiative/', '2012-05-29', 'D07 : projet pilote de carte d''assurance santé, 400 premiers bénéficiaires. Couverture finale / pérennité du programme non documentée.', 'Non vérifié'),
  ((select id from candidates where full_name ilike '%martel%' limit 1), 'Projet touristique Île-à-Vache', 'Programme ou engagement public', 'CaribJournal', 'https://www.caribjournal.com/?p=29935', '2012-12-01', 'D08 : projet touristique annoncé par le PM Lamothe, budget déclaré entre 160M$ et 260M$ (chiffres incohérents selon les sources). Fermiers locaux non consultés selon des sources critiques.', 'Non vérifié'),
  ((select id from candidates where full_name ilike '%martel%' limit 1), 'Programme « Katye Pam Poze »', 'Programme ou engagement public', 'CaribJournal', 'https://www.caribjournal.com/2012/03/19/haitis-jacmel-talks-decentralization/', '2012-03-19', 'D09 : programme présenté comme outil d''ancrage local / décentralisation. Aucune preuve trouvée d''un report des élections locales sous Martelly.', 'Non vérifié'),
  ((select id from candidates where full_name ilike '%martel%' limit 1), 'Initiatives environnementales — « année de l''environnement »', 'Document officiel / source primaire', 'UNEP (Programme des Nations Unies pour l''environnement)', 'https://www.unep.org/en/news-and-stories/press-release/mountains-sea-investing-haitis-environmental-resources-cause', '2013-01-01', 'D10 : 2013 déclarée « année de l''environnement », objectif de plantation de 50M arbres/an, 9 zones côtières/marines protégées créées. Résultat final (couverture forestière) non documenté comme atteint.', 'Non vérifié'),
  ((select id from candidates where full_name ilike '%martel%' limit 1), 'Gouvernance par décret après dissolution du Parlement', 'Fait documenté', 'Al Jazeera', 'https://www.aljazeera.com/news/2015/1/14/haiti-in-quandary-after-parliament-dissolves', '2015-01-14', 'D11/D12 : à partir de janvier 2015, le Sénat ne pouvait plus former le quorum ; Martelly a gouverné par décret sans supervision législative jusqu''à la fin de son mandat (février 2016).', 'Non vérifié'),
  ((select id from candidates where full_name ilike '%martel%' limit 1), 'Amendement constitutionnel concernant le vodou', 'Fait documenté', 'Département d''État américain (rapport sur la liberté religieuse)', 'https://hrvoices.org/assets/attachments/documents/2015.state.dept.religion.haiti.pdf', '2012-06-01', 'D13 : Martelly a promulgué un amendement constitutionnel concernant le statut du vodou, en juin 2012.', 'Non vérifié'),
  ((select id from candidates where full_name ilike '%martel%' limit 1), 'Modernisation des Forces armées d''Haïti — rapport ONU', 'Document officiel / source primaire', 'Conseil de sécurité des Nations Unies', 'https://www.securitycouncilreport.org/atf/cf/%7B65BFCF9B-6D27-4E9C-8CD3-CF6E4FF96FF9%7D/Haiti%20S%202012%20128.pdf', '2012-05-01', 'D18 : commission civile créée (déc. 2011) pour étudier la restauration des Forces armées d''Haïti (démantelées en 1995) ; rapport préliminaire (mai 2012). Le rapport ONU appelle à une supervision démocratique de toute nouvelle force armée.', 'Non vérifié');
